test('typed export IPC sends only typed session ID and database binding, honors cancellation and current read access',async()=>{await savedDraft();const session=await page.evaluate(()=>__aiDB.inventorySessions[0]);await page.evaluate(session=>{data.inventorySessions=[session];Object.assign(_sync.platform,{storageKind:'sqlite',schemaVersion:6,readOnly:false});window.__actualExports=[];electronAPI.assetInventoryExport=async payload=>{__actualExports.push(payload);return{ok:false,cancelled:true};};},session);const result=await page.evaluate(id=>assetInventoryExportDocument({format:'pdf',sessionId:id}),session.id);assert.deepEqual(result,{ok:false,cancelled:true});const request=await page.evaluate(()=>__actualExports[0]);assert.deepEqual(Object.keys(request).sort(),['databaseToken','format','sessionId']);assert.equal(request.sessionId,session.id);await page.evaluate(()=>{_sync.access={readable:[],writable:[]};});const denied=await page.evaluate(id=>assetInventoryExportDocument({format:'xlsx',sessionId:id}),session.id);assert.equal(denied.ok,false);assert.match(denied.error,/доступ/i);assert.equal(await page.evaluate(()=>__actualExports.length),1);assert.equal(await page.evaluate(()=>__writes),0);});
test('oversized selected source never leaves the browser and retains the users explicit mapping',async()=>{await installPrivateFileService();const form=await openFiles();await chooseSource(form);await form.locator('[name=defaultObjectName]').fill('Explicit object retained');await form.locator('[name=file]').setInputFiles({name:'oversized.json',mimeType:'application/json',buffer:Buffer.alloc(25*1024*1024+1)});await form.locator('[data-ai-file-review]').click();await page.waitForFunction(()=>document.querySelector('[data-ai-file-error]')?.textContent.includes('25 МБ'));assert.equal(await page.evaluate(()=>__fileRequests.length+__fileCommands.length+__writes),0);assert.equal(await form.locator('[name=defaultObjectName]').inputValue(),'Explicit object retained');assert.equal(await form.locator('[name=date]').inputValue(),'2026-10-25');assert.equal(await form.locator('[data-ai-file-commit]').isDisabled(),true);});
test('a source changed during asynchronous staging cannot become a reviewed import',async()=>{await installPrivateFileService();const form=await openFiles();await chooseSource(form);await page.evaluate(()=>{__fileHold=true;});await form.locator('[data-ai-file-review]').click();await page.waitForFunction(()=>typeof __fileRelease==='function');await page.evaluate(()=>{data.inventoryItems[0].note='Concurrent independent current source change';__fileRelease();});await page.waitForFunction(()=>document.querySelector('[data-ai-file-error]')?.textContent.includes('Исходные данные'));assert.equal(await form.locator('[data-ai-file-confirm]').isVisible(),false);assert.equal(await form.locator('[name=file]').evaluate(input=>input.files[0].name),'synthetic-source.json');assert.equal(await form.locator('[name=reason]').inputValue(),'Explicit entire-source private import');assert.equal(await page.evaluate(()=>__fileRequests.length),1);assert.equal(await page.evaluate(()=>__fileCommands.length+__writes),0);});
test('a decoder error without a database token remains an actionable source error with the selected file intact',async()=>{await installPrivateFileService();const form=await openFiles();await chooseSource(form);await page.evaluate(()=>{electronAPI.importSource=async payload=>{__fileRequests.push(payload);return{ok:false,code:'INVENTORY_LEGACY_SCHEMA',error:'SYNTHETIC UNSUPPORTED SOURCE HEADER',issues:[{code:'HEADER',message:'Correct the source header'}]};};});await form.locator('[data-ai-file-review]').click();await page.waitForFunction(()=>document.querySelector('[data-ai-file-error]')?.textContent.includes('UNSUPPORTED SOURCE HEADER'));assert.match(await form.locator('[data-ai-file-preview]').innerText(),/Correct the source header/);assert.equal(await form.locator('[name=file]').evaluate(input=>input.files[0].name),'synthetic-source.json');assert.equal(await form.locator('[name=reason]').inputValue(),'Explicit entire-source private import');assert.equal(await form.locator('[data-ai-file-commit]').isDisabled(),true);assert.equal(await page.evaluate(()=>__fileCommands.length+__writes),0);});
test('native quantity and inventory import buttons prepare a compatible copy or open the production SQLite wizard',async()=>{
 await installPrivateFileService();
 await page.evaluate(()=>{
  window.__upgradeInspections=0;window.__upgradeWrites=0;
  electronAPI.inspectSchemaUpgrade=async()=>{__upgradeInspections++;return{ok:true,sourceFormat:_sync.platform.storageKind,targetDescriptor:{schemaVersion:6},sourceFingerprint:'sha256:'+'a'.repeat(64),counts:[]};};
  electronAPI.upgradeSchemaCopy=async()=>{__upgradeWrites++;throw Error('Copy publication requires explicit confirmation');};
 });
 const initial=await page.evaluate(()=>JSON.stringify(data));
 for(const render of ['renderObjectQuantitySection','renderAssetInventorySection']){
  for(const mode of ['json','schema5','capability']){
   await page.evaluate(({render,mode})=>{Object.assign(_sync.platform,{storageKind:mode==='json'?'json':'sqlite',schemaVersion:mode==='schema5'?5:6,readOnly:false});const profile=_sync.platform.negotiation.selectedProfile;profile.capabilities=profile.capabilities.filter(cap=>cap.name!=='inventoryV1');if(mode!=='capability')profile.capabilities.push({name:'inventoryV1',version:1});window[render]();},{render,mode});
   for(const action of ['importLegacy','importXlsx']){
    assert.equal(await page.locator('[data-ai-action='+action+']').isDisabled(),false);
    await page.locator('[data-ai-action='+action+']').click();
    const upgrade=page.locator('#lifecycleUpgradeForm');await upgrade.waitFor();
    assert.equal(await page.locator('[data-ai-files-form]').count(),0);
    assert.equal(await upgrade.locator('[name=confirm]').isChecked(),false);
    assert.equal(await upgrade.locator('[name=targetFormat]').inputValue(),'sqlite');
    assert.equal(await page.evaluate(()=>__fileRequests.length+__fileCommands.length+__upgradeWrites+__writes),0);
    await page.evaluate(()=>closeModal('wfModal'));assert.equal(await page.locator('#wfModal').evaluate(node=>node.classList.contains('open')),false);
   }
  }
  await page.evaluate(render=>{Object.assign(_sync.platform,{storageKind:'sqlite',schemaVersion:6,readOnly:false});_sync.platform.negotiation.selectedProfile.capabilities.push({name:'inventoryV1',version:1});window[render]();},render);
  assert.equal(await page.locator('[data-ai-action=importXlsx]').isDisabled(),false);
  await page.locator('[data-ai-action=importXlsx]').click();
  const form=page.locator('[data-ai-files-form]');await form.waitFor();
  assert.equal(await form.locator('[name=format]').inputValue(),'auto');
  assert.equal(await form.locator('[name=file]').getAttribute('accept'),'.xls,.xlsx');
  assert.equal(await form.locator('[name=date]').inputValue(),'');
  await form.locator('[data-ai-file-review]').click();
  assert.match(await form.locator('[data-ai-file-error]').innerText(),/Выберите исходный файл/);
  await page.locator('[data-ai-file-close]').click();await form.waitFor({state:'detached'});
  await page.evaluate(render=>{_sync.platform.readOnly=true;window[render]();},render);
  for(const action of ['importLegacy','importXlsx'])assert.equal(await page.locator('[data-ai-action='+action+']').isDisabled(),true);
 }
 assert.equal(await page.evaluate(()=>__upgradeInspections),12);
 assert.equal(await page.evaluate(()=>JSON.stringify(data)),initial);
 assert.equal(await page.evaluate(()=>__fileRequests.length+__fileCommands.length+__upgradeWrites+__writes),0);
});
